-- ============================================================================
-- 2026-09-13 — lamap-db: pin search_path on 140 SECURITY DEFINER functions (hardening, zero behaviour change)
-- ============================================================================
-- WHAT: ALTER FUNCTION ... SET search_path = <path>. Metadata only: no data, table, view, grant or function
-- body is touched. Reversible instantly: 2026-09-13_lamap_db_search_path_pinning_ROLLBACK.sql
-- (RESET search_path; prior proconfig saved in lamap-db backup.search_path_pin_20260913).
--
-- WHY: SECURITY DEFINER functions without a fixed search_path resolve unqualified names through the
-- CALLER's path (search_path hijack class). Low severity today (anon/authenticated cannot create objects
-- anywhere), but it is the scanner finding on the Lamap repo.
--
-- HOW EQUIVALENCE WAS PROVEN (before applying):
--  1. Static: every unqualified identifier/operator of each function AND of everything that runs under it
--     (unpinned callees, trigger functions of tables it touches, policy/default expressions) was resolved
--     against the live catalog under every real caller path: PostgREST RPC per exposed schema
--     (<schema>, public, extensions | <schema>, public), cron/postgres (public, extensions), anon/authenticated
--     direct (public — their role path names schema silver, which no longer exists), supabase_admin
--     (public, auth, extensions). Functions whose names resolve to different schemas depending on the
--     caller were EXCLUDED (behaviour already caller-dependent), as were functions that create objects
--     unqualified, touch search_path, or execute caller-supplied SQL.
--  2. PostgreSQL itself, in rolled-back transactions: plpgsql_check dependency sets (92 PL/pgSQL functions
--     with dependencies) and BEGIN ATOMIC recompilation with pg_depend bindings (49 SQL functions) —
--     pinned path vs website path vs direct path: 0 differences, 0 new errors, 0 compile failures.
--  3. Live outputs: md5 of the results of all 22 argument-free STABLE functions, called as role anon with the
--     PostgREST path, in READ ONLY transactions — identical twice before, identical after.
--  4. Live PostgREST calls after applying (public, lamap_app): HTTP 200.
--  Overhead of the SET clause measured at ~0.3 µs per call; the only per-row use (policy on
--  entity_functions) is on a 0-row table.
--
-- NOT PINNED (left exactly as they were):
--   ask_lamap.execute_query(query_text text): runs caller-supplied SQL; resolution depends on the caller
--   lamap_app.get_property_categories(p_commune text, p_canton text): ambiguous: categories[rel]->['content_sites', 'lamap_app', 'public']
--   lamap_app.get_building_typologies(p_commune text, p_canton text): ambiguous: typologies[rel]->['ask_lamap', 'public']
--   lamap_app.calculate_rental_estimation(p_user_id uuid, p_property_type text, p_property_subtype_id uuid, p_commune text, p_npa text, p_surface_m2 numeric, p_selected_feature_ids uuid[], p_address_id uuid, p_plot_id uuid, p_street_name text, p_street_number text, p_num_rooms numeric, p_num_bedrooms integer, p_num_bathrooms integer, p_construction_year integer, p_user_notes text, p_unit_id uuid, p_base_rent numeric): ambiguous: user_notes[rel]->['lamap_app', 'public']
--   lamap_app.calculate_rental_estimation(p_user_id uuid, p_property_type text, p_property_subtype_id uuid, p_commune text, p_npa text, p_surface_m2 numeric, p_selected_feature_ids uuid[], p_address_id uuid, p_plot_id uuid, p_street_name text, p_street_number text, p_num_rooms numeric, p_num_bedrooms integer, p_num_bathrooms integer, p_construction_year integer, p_user_notes text, p_unit_id uuid, p_base_rent numeric, p_latitude numeric, p_longitude numeric): ambiguous: user_notes[rel]->['lamap_app', 'public']
--   lamap_app.calculate_estimation_national(p_user_id uuid, p_property_type text, p_property_subtype_id uuid, p_commune text, p_canton text, p_npa text, p_surface_m2 numeric, p_selected_feature_ids uuid[], p_address_id uuid, p_plot_id uuid, p_street_name text, p_street_number text, p_num_rooms numeric, p_num_bathrooms integer, p_construction_year integer, p_user_notes text): ambiguous: user_notes[rel]->['lamap_app', 'public']
--   lamap_app.calculate_rental_estimation(p_user_id uuid, p_property_type text, p_property_subtype_id uuid, p_commune text, p_npa text, p_surface_m2 numeric, p_selected_feature_ids uuid[], p_address_id uuid, p_plot_id uuid, p_street_name text, p_street_number text, p_num_rooms numeric, p_num_bedrooms integer, p_num_bathrooms integer, p_construction_year integer, p_user_notes text, p_unit_id uuid, p_base_rent numeric, p_latitude numeric, p_longitude numeric, p_no_commune_no_parcelle text): ambiguous: user_notes[rel]->['lamap_app', 'public']
--   lamap_app.generate_watchlist_notifications(): ambiguous: sad[rel]->['ask_lamap', 'public']
--   lamap_app.scan_keywords_for_matches(): ambiguous: unaccent[func]->['ask_lamap', 'public']
--   public.content_insert_article(p_site text, p_title text, p_slug text, p_excerpt text, p_body_html text, p_focus_keyphrase text, p_seo_title text, p_seo_description text, p_topic_seed text, p_references_used jsonb, p_category_slug text, p_tags text[], p_reading_time integer): ambiguous: tags[rel]->['content_sites', 'lamap_app', 'public']
--   public.add_keyword(p_keyword text, p_search_transactions_acheteur boolean, p_search_transactions_vendeur boolean, p_search_sad_mandataire boolean, p_search_sad_proprietaire boolean, p_search_entities boolean, p_auto_add_to_watchlist boolean, p_notify_email boolean, p_notify_app boolean, p_notes text): ambiguous: unaccent[func]->['ask_lamap', 'public']
--   public.content_insert_article(p_site text, p_title text, p_slug text, p_excerpt text, p_body_html text, p_focus_keyphrase text, p_seo_title text, p_seo_description text, p_topic_seed text, p_references_used jsonb, p_category_slug text, p_tags text[], p_reading_time integer, p_og_image_url text): ambiguous: tags[rel]->['content_sites', 'lamap_app', 'public']
--   public.exec_sql(query text): runs caller-supplied SQL; resolution depends on the caller
--   (5 functions pinned earlier today in 2026-09-13_alert_triage_fixes.sql re-verified with the same method.)
-- ============================================================================
BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE TABLE IF NOT EXISTS backup.search_path_pin_20260913 (fn_oid oid, signature text, proconfig_before text[], pinned_path text, applied_at timestamptz DEFAULT now());
COMMIT;
